import mlflow

mlflow.set_experiment("rag-app")

@mlflow.trace(span_type="RETRIEVER")
def retrieve(question: str) -> list[str]:
    return ["MLflow traces are trees of spans."]

@mlflow.trace(span_type="LLM")
def fake_llm(prompt: str) -> str:
    return "A trace is a tree of spans."   # stand-in for a real model call

@mlflow.trace
def answer(question: str) -> str:
    docs = retrieve(question)
    with mlflow.start_span("build_prompt") as span:
        prompt = f"Context: {docs}\nQ: {question}"
        span.set_attribute("n_docs", len(docs))
    return fake_llm(prompt)

print(answer("What is a trace?"))
trace = mlflow.get_trace(mlflow.get_last_active_trace_id(), flush=True)
print([s.name for s in trace.data.spans])  # ['answer', 'retrieve', 'build_prompt', 'fake_llm']

import mlflow
from mlflow.genai.scorers import scorer

def my_app(question: str) -> str:            # stand-in for an LLM app
    return "Paris is the capital of France." if "France" in question else "I am not sure."

@scorer
def mentions_expected(outputs, expectations) -> bool:
    return expectations["expected_response"].lower() in outputs.lower()

@scorer
def concise(outputs) -> bool:
    return len(outputs.split()) <= 12

data = [
    {"inputs": {"question": "Capital of France?"}, "expectations": {"expected_response": "Paris"}},
    {"inputs": {"question": "Capital of Peru?"}, "expectations": {"expected_response": "Lima"}},
]
result = mlflow.genai.evaluate(data=data, predict_fn=my_app,
                               scorers=[mentions_expected, concise])
print(result.metrics)
# {'mentions_expected/mean': 0.5, 'concise/mean': 1.0}
